<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1220;
      --panel: rgba(15, 23, 42, 0.92);
      --panel-border: rgba(148, 163, 184, 0.16);
      --text: #e5e7eb;
      --muted: #94a3b8;
      --accent: #60a5fa;
      --accent-strong: #3b82f6;
      --error: #f87171;
      --success: #34d399;
      --field-bg: #0f172a;
      --field-border: #334155;
      --field-focus: rgba(96, 165, 250, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(59, 130, 246, 0.18), transparent 36%),
        linear-gradient(180deg, #050816 0%, var(--bg) 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 24px;
    }

    .support-card {
      width: min(100%, 640px);
      background: var(--panel);
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      box-shadow: 0 30px 80px rgba(0, 0, 0, 0.45);
      backdrop-filter: blur(18px);
      padding: 32px;
    }

    .eyebrow {
      margin: 0 0 8px;
      color: var(--accent);
      font-size: 0.85rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      font-weight: 700;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.8rem, 3vw, 2.4rem);
      line-height: 1.1;
    }

    .subtitle {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-size: 0.95rem;
      font-weight: 600;
    }

    input {
      width: 100%;
      border: 1px solid var(--field-border);
      background: var(--field-bg);
      color: var(--text);
      border-radius: 14px;
      padding: 14px 16px;
      font: inherit;
      outline: none;
      transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px var(--field-focus);
    }

    input[aria-invalid="true"] {
      border-color: rgba(248, 113, 113, 0.9);
      box-shadow: 0 0 0 4px rgba(248, 113, 113, 0.16);
    }

    .help-text {
      margin: 0;
      color: var(--muted);
      font-size: 0.88rem;
      line-height: 1.5;
    }

    .error-text {
      min-height: 1.2em;
      margin: 0;
      color: var(--error);
      font-size: 0.88rem;
      line-height: 1.4;
    }

    .actions {
      margin-top: 6px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      flex-wrap: wrap;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      color: white;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 18px 40px rgba(59, 130, 246, 0.35);
      transition: transform 0.18s ease, filter 0.18s ease;
    }

    button:hover {
      filter: brightness(1.05);
      transform: translateY(-1px);
    }

    button:active {
      transform: translateY(0);
    }

    .status {
      min-height: 1.25em;
      color: var(--success);
      font-size: 0.95rem;
      font-weight: 600;
    }

    @media (max-width: 520px) {
      .support-card {
        padding: 22px;
        border-radius: 20px;
      }

      button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="support-card">
    <p class="eyebrow">Support</p>
    <h1>Contact our team</h1>
    <p class="subtitle">Send us your details and we’ll get back to you as soon as possible.</p>

    <form id="supportForm" novalidate>
      <div class="form-field">
        <label for="fullName">Full name *</label>
        <input id="fullName" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required />
        <p class="error-text" id="fullNameError" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="emailAddress">Email address *</label>
        <input id="emailAddress" name="emailAddress" type="email" autocomplete="email" placeholder="jane@example.com" required />
        <p class="error-text" id="emailAddressError" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phoneNumber">Phone number</label>
        <input id="phoneNumber" name="phoneNumber" type="tel" autocomplete="tel" placeholder="+1 (555) 123-4567" inputmode="tel" />
        <p class="help-text">Optional. Use a format like +1 (555) 123-4567.</p>
        <p class="error-text" id="phoneNumberError" aria-live="polite"></p>
      </div>

      <div class="actions">
        <button type="submit">Submit request</button>
        <p class="status" id="formStatus" aria-live="polite"></p>
      </div>
    </form>
  </main>

  <script>
    const form = document.getElementById("supportForm");
    const fields = {
      fullName: {
        input: document.getElementById("fullName"),
        error: document.getElementById("fullNameError"),
        validate(value) {
          if (!value.trim()) return "Full name is required.";
          return "";
        }
      },
      emailAddress: {
        input: document.getElementById("emailAddress"),
        error: document.getElementById("emailAddressError"),
        validate(value) {
          if (!value.trim()) return "Email address is required.";
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
            return "Enter a valid email address.";
          }
          return "";
        }
      },
      phoneNumber: {
        input: document.getElementById("phoneNumber"),
        error: document.getElementById("phoneNumberError"),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) return "";
          if (!/^\+?[0-9][0-9\s().-]{6,}[0-9]$/.test(trimmed)) {
            return "Enter a valid phone number using the expected format.";
          }
          return "";
        }
      }
    };

    const status = document.getElementById("formStatus");

    function validateField(fieldName) {
      const field = fields[fieldName];
      const message = field.validate(field.input.value);
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
      return !message;
    }

    Object.entries(fields).forEach(([fieldName, field]) => {
      ["input", "blur"].forEach((eventName) => {
        field.input.addEventListener(eventName, () => validateField(fieldName));
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isValid = Object.keys(fields).every(validateField);

      if (!isValid) {
        status.textContent = "";
        return;
      }

      status.textContent = "Your support request is ready to send.";
      form.reset();
      Object.values(fields).forEach((field) => field.input.setAttribute("aria-invalid", "false"));
      Object.values(fields).forEach((field) => (field.error.textContent = ""));
    });
  </script>
</body>
</html>
